  const visibleRecords=records.filter(r=>!r.archived&&(user.role===ROLES.STUDENT||user.role===ROLES.ADMIN||user.role===ROLES.PRINCIPAL||user.role===ROLES.SECURITY||matchesScope(r,user)));
  const previewUpdate=(id,changes)=>setRecords(rows=>rows.map(r=>r.id===id?{...r,...changes}:r));
  const alerts=visibleRecords.filter(r=>user.role===ROLES.STUDENT?!['CLEARED'].includes(r.status):QUEUE_FOR_ROLE[user.role]?r.status===QUEUE_FOR_ROLE[user.role]:['APPROVED','CURRENTLY_OUT'].includes(r.status)).slice(0,8);
